sys_script.script:
(function executeRule(current, previous) {
    var areaType = current.getValue('area_type');
    var parentId = current.getValue('parent');

    // City must not have a parent
    if (areaType === 'city' && parentId) {
        gs.addErrorMessage('A City area cannot have a parent.');
        current.setAbortAction(true);
        return;
    }

    // Village must have a parent whose area_type is 'city'
    if (areaType === 'village') {
        if (!parentId) {
            gs.addErrorMessage('A Village area must have a parent.');
            current.setAbortAction(true);
            return;
        }
        var parentGr = new GlideRecord('x_1966159_utilit_0_area');
        if (parentGr.get(parentId)) {
            if (parentGr.getValue('area_type') !== 'city') {
                gs.addErrorMessage('A Village area must have a City as its parent.');
                current.setAbortAction(true);
                return;
            }
        }
    }

    // Street must have a parent whose area_type is 'village'
    if (areaType === 'street') {
        if (!parentId) {
            gs.addErrorMessage('A Street area must have a parent.');
            current.setAbortAction(true);
            return;
        }
        var parentGr2 = new GlideRecord('x_1966159_utilit_0_area');
        if (parentGr2.get(parentId)) {
            if (parentGr2.getValue('area_type') !== 'village') {
                gs.addErrorMessage('A Street area must have a Village as its parent.');
                current.setAbortAction(true);
                return;
            }
        }
    }

    // Prevent circular references
    if (parentId) {
        var currentSysId = current.getUniqueValue();
        var checkId = parentId;
        var visited = {};

        while (checkId) {
            if (checkId === currentSysId) {
                gs.addErrorMessage('Circular reference detected in area hierarchy.');
                current.setAbortAction(true);
                return;
            }
            if (visited[checkId]) {
                break;
            }
            visited[checkId] = true;
            var gr = new GlideRecord('x_1966159_utilit_0_area');
            if (gr.get(checkId)) {
                checkId = gr.getValue('parent');
            } else {
                break;
            }
        }
    }
})(current, previous);
